css:
.d-ss{position:absolute;top:40px;left:10px;width:210px;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:var(--paper);box-shadow:0 14px 30px #20241e1f;font-size:11.5px;z-index:5}
.d-ss b{display:block;font-size:10px;letter-spacing:.08em;color:var(--faint);margin:6px 0 3px}
.d-ss p{margin:0 0 3px;color:var(--muted)}
.d-ss kbd{font:10.5px ui-monospace,Consolas,monospace;border:1px solid var(--line);border-bottom-width:2px;border-radius:2px;padding:0 5px}
.d-btn{font:inherit;font-size:13px;padding:8px 16px;border-radius:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;transition:transform .16s var(--ease),background-color .16s,color .16s,border-color .16s}
.d-btn:hover{box-shadow:0 6px 18px #20241e14}
.d-btn:active{transform:scale(.97)}

init:
root => {
    const box = root.querySelector('.d-ss');
    root.querySelector('[data-ss]').onclick = () => box.hidden = !box.hidden;
    const scope = root.closest('.card') || document; scope.addEventListener('keydown', e => { if (e.key === '?') { box.hidden = !box.hidden; } });
  }
